from __future__ import annotations
from dataclasses import dataclass

@dataclass(frozen=True)
class State:
    l: int
    m: int

def build_transition_graph(l_max: int) -> dict[State, set[State]]:
    vertices = [State(l, m) for l in range(l_max + 1) for m in range(-l, l + 1)]
    graph = {v: set() for v in vertices}
    universe = set(vertices)
    for v in vertices:
        if v.l == l_max:
            continue
        for dm in (-1, 0, 1):
            w = State(v.l + 1, v.m + dm)
            if w in universe:
                graph[v].add(w)
                graph[w].add(v)
    return graph

